// Warn WARN_DAYS ahead. Nodes with key expiry disabled cannot expire.
// All-clear runs stay silent except on the weekly heartbeat day, so a
// long quiet stretch still proves the workflow is alive.
const WARN_DAYS = 7;
const HEARTBEAT_DAY = 1; // 0=Sun, 1=Mon

const devices = $input.first().json.devices || [];
const now = Date.now();

const expired = [], expiring = [], healthy = [];
let disabled = 0;

for (const d of devices) {
  const name = String(d.name || d.hostname || d.id || '?').split('.')[0];
  if (d.keyExpiryDisabled) { disabled++; continue; }
  const t = Date.parse(d.expires);
  // Tailscale uses year 1 as the zero value for "no expiry".
  if (!t || new Date(t).getUTCFullYear() < 2000) continue;
  const days = Math.floor((t - now) / 86400000);
  const row = { name, days, date: new Date(t).toISOString().slice(0, 10) };
  if (days < 0) expired.push(row);
  else if (days <= WARN_DAYS) expiring.push(row);
  else healthy.push(row);
}

const byDays = (a, b) => a.days - b.days;
expired.sort(byDays); expiring.sort(byDays); healthy.sort(byDays);

if (expired.length || expiring.length) {
  const lines = [
    ...expired.map(r => `EXPIRED ${Math.abs(r.days)}d ago: ${r.name} (${r.date})`),
    ...expiring.map(r => `expires in ${r.days}d: ${r.name} (${r.date})`),
    'Re-authenticate the machine, or disable key expiry in the admin console.',
  ];
  return [{ json: {
    title: 'Tailscale key expiry',
    priority: 'high',
    tags: 'warning',
    message: lines.join('\n'),
  } }];
}

// Nothing to warn about. Only speak up on the heartbeat day.
if (new Date().getDay() !== HEARTBEAT_DAY) return [];

const nearest = healthy[0];
return [{ json: {
  title: 'Tailscale keys: all clear',
  priority: 'default',
  tags: 'white_check_mark',
  message: [
    nearest
      ? `Nearest: ${nearest.name} in ${nearest.days}d (${nearest.date})`
      : 'No devices with expiry enabled.',
    `${devices.length} devices checked, ${disabled} with expiry disabled`,
  ].join('\n'),
} }];
